#include "SimulationPage.h"

#include "WebAssets.h" // generated by CMake from web/simulation.html

#include <fstream>
#include <iomanip>
#include <sstream>
#include <stdexcept>

namespace attitude {

namespace {

/** Replace the first occurrence of `token` in `text` with `value`. */
void replaceToken(std::string& text, const std::string& token, const std::string& value) {
    const auto pos = text.find(token);
    if (pos == std::string::npos) {
        throw std::runtime_error("Template is missing placeholder " + token);
    }
    text.replace(pos, token.size(), value);
}

/** Samples as a JSON array of [t, ax, ay, az, pitch, roll] rows. */
std::string toJson(const std::vector<AccelRecord>& samples,
                   const std::vector<EstimationRecord>& estimates) {
    std::ostringstream out;
    out << std::fixed << std::setprecision(4) << '[';
    for (std::size_t i = 0; i < samples.size(); ++i) {
        const auto& s = samples[i];
        const auto& e = estimates[i];
        if (i) out << ',';
        out << '[' << s.timestampMs << ',' << s.accel.x << ',' << s.accel.y << ',' << s.accel.z
            << ',' << e.attitude.pitchDeg << ',' << e.attitude.rollDeg << ']';
    }
    out << ']';
    return out.str();
}

} // namespace

std::string SimulationPage::render(const std::vector<AccelRecord>& samples,
                                   const std::vector<EstimationRecord>& estimates,
                                   const std::string& equationsName,
                                   const std::string& sourceName) {
    if (samples.size() != estimates.size()) {
        throw std::invalid_argument("samples and estimates differ in length");
    }
    std::string html = kSimulationHtml;
    replaceToken(html, "__SOURCE_NAME__", sourceName);
    replaceToken(html, "__EQUATIONS__", equationsName);
    replaceToken(html, "__DATA__", toJson(samples, estimates));
    return html;
}

void SimulationPage::write(const std::string& path,
                           const std::vector<AccelRecord>& samples,
                           const std::vector<EstimationRecord>& estimates,
                           const std::string& equationsName,
                           const std::string& sourceName) {
    std::ofstream out(path, std::ios::binary);
    if (!out) throw std::runtime_error("Could not write " + path);
    out << render(samples, estimates, equationsName, sourceName);
}

} // namespace attitude
